package orm

import (
	"strconv"
	"strings"
)

// Dialect selects the SQL syntax generated by the query builders.
type Dialect int

const (
	// MySQL (and MariaDB): identifiers in `backticks`, placeholders "?".
	MySQL Dialect = iota
	// Postgres: identifiers in "double quotes", placeholders $1, $2, ...
	//
	// Note: quoted identifiers are case-sensitive in PostgreSQL, and unquoted
	// names in CREATE TABLE are folded to lowercase. Since the builders always
	// quote, write table and column names exactly as stored (usually lowercase):
	// Select("id"), not Select("ID").
	Postgres
)

// DefaultDialect is the dialect used by builders created with SelectQuery,
// InsertQuery, UpdateQuery and DeleteQuery. Set it once at startup, before
// building queries (it is not safe to change it concurrently), or call
// Dialect() on the single builder.
var DefaultDialect = MySQL

func (d Dialect) String() string {
	switch d {
	case MySQL:
		return "mysql"
	case Postgres:
		return "postgres"
	default:
		return "Dialect(" + strconv.Itoa(int(d)) + ")"
	}
}

func (d Dialect) valid() bool {
	return d == MySQL || d == Postgres
}

// render converts a fragment generated by the builders (always written with
// `backticks` and "?" placeholders) to the dialect. n is the number of
// placeholders already emitted in the query and is updated.
//
// It must only be applied to text generated by the builders: identifiers are
// validated by regex and never contain backticks or "?", so a plain character
// substitution is safe. Never apply it to user-written SQL (SetRaw).
func (d Dialect) render(fragment string, n *int) string {
	if d != Postgres {
		*n += strings.Count(fragment, "?")
		// MySQL has no ILIKE; LIKE is case-insensitive with _ci collations.
		// Identifiers are always quoted, so " ILIKE " can only be the operator.
		return strings.ReplaceAll(fragment, " ILIKE ", " LIKE ")
	}
	var sb strings.Builder
	sb.Grow(len(fragment) + 8)
	for i := 0; i < len(fragment); i++ {
		switch c := fragment[i]; c {
		case '`':
			sb.WriteByte('"')
		case '?':
			*n++
			sb.WriteByte('$')
			sb.WriteString(strconv.Itoa(*n))
		default:
			sb.WriteByte(c)
		}
	}
	return sb.String()
}
